CMONS0        LD A,(HL)        INC A       RET ZscmonX=$+1        SUB 0        CP viewrange*2+1        JP NC,SCMONNx        INC L        inc L        LD A,(HL)scmonY=$+1        SUB 0        CP viewrange*2+1        JR C,SCMONY        LD A,L        ADD A,6        LD L,A        JP NC,SCMONS0SCMxIH  INC H        JP SCMONS0SCMONY  DEC L        dec L        dec L        LD C,(HL)        INC L        LD B,(HL) ;Xx        INC L        LD E,(HL)        INC L        LD D,(HL) ;Yy        INC L       PUSH HL        PUSH BC        LD C,(HL) ;phase        INC L       LD L,(HL) ;TYPE       LD B,0,H,B        ADD HL,HL        ADD HL,HL        ADD HL,HL        ADD HL,BC        ADD HL,HL        LD BC,MONSTAB        ADD HL,BC       LD A,(HL) ;texx       LD HX,A       INC HL       LD A,(HL) ;ID        POP BC;calculate sprite position        LD HL,(curYy)        SBC HL,DE ;Yy        EXD         LD HL,(curXx)        SBC HL,BC ;Xx        CALL OBJMUL       ;BC=dist       ;DE=xscr       IF lores        SRA D        RR E       ENDIF         LD HL,pixperchr*scrwid/2-256        SBC HL,DE        INC H       jr NZ,SCANnSPR ;X out of screen       IF lores        BIT 7,L       jr NZ,SCANnSPR ;X out of screen       ENDIF ;write data to cursprites       PUSH BC        EXX        POP BC        LD HL,cursprites+((-2)&0xff)SCANsort0        INC L        inc L        LD A,(HL)        OR A        jr Z,SCANins        INC L        LD E,(HL)        INC L        LD D,(HL)        EXD         SBC HL,BC        EXD         jr NC,SCANsort0        DEC L        dec LSCANins       PUSH BCscaneof=$+1        LD DE,0        LD A,E        SUB L        INC A ;bytes to move        LD C,A        LD B,0        LD H,D,L,E        LD A,E        ADD A,4        LD E,A        LD (scaneof),A        LDDR         INC HL       POP BC        LD A,1;???A=object# (ID,texx);BC'=dist;L'=xscr        LD (HL),A        INC L        LD (HL),C        INC L        LD (HL),B        INC L        EXX         LD A,L        EXX         LD (HL),A ;xscr        INC L        EXX SCANnSPR ;       POP HL        INC L        inc L        inc L        inc HL       INC L        JP SCMONS0DRAWSPRITES        LD IY,curspritesDRAWSPRITES0 ;        LD A,(IY)        OR A        RET Z        INC IY        LD C,(IY)        INC IY        LD B,(IY)        INC IY        LD L,(IY)        INC IY;???A=object# (ID,texx)        EXX          LD D,#EA ;ID (TODO читать из описателя спрайта)        EXX ;L=xscr;BC=dist       LD HX,#C0 ;texx=#80..#FF        INC B        DJNZ gFILLNCLOSE        LD A,96;64        CP C        jr C,$+3        LD C,AgFILLNCLOSE       PUSH BC ;dist;приводим к 128..255        LD DE,#000        INC B        DEC B        LD A,C        jr Z,MOTOLOGRLQ       DUP 5;6        INC D        SRL B        RRA         jr Z,MOTOLOGRLE       EDUP MOTOLOGRLQ ;        OR A        JP M,$+5 ;>=128        LD A,128 ;<128MOTOLOGRLE ;        LD C,A ;128..255 ;D=0..5        LD B,tlogd/256        LD A,(BC) ;log(dist) = 128..255 for arg>=128       SUB 16;64                 ;0..127 for arg=64..127        LD C,A                ;0 for arg<64        LD B,tlogd2sca/256         SRA D         RR E ;DE=+0,+#80,..+#300        EXD         ADD HL,BC        LD C,(HL) ;scale        EXD       ;       POP DE ;dist       IF loresspr        SLA E        RL D       ENDIF         SLA E        RL D ;DE=texx step       IF loresspr_hires|optresspr       RES 0,L       ENDIF         LD H,distbuf/256+2 ;ID,texx,dist        LD A,C ;scale        CP (HL)        CALL NC,DRAWSPRITE ;object center is visible        JP DRAWSPRITES0OBJMULQ        POP AF ;X       LD D,#40 ;X out of screen        RET ;пересчет координат объекта (Xx=HL, Yy=DE);в координаты на экране (DE=xscr, BC=расстояние)OBJMUL        PUSH HL ;X       PUSH DE ;Y       PUSH HL ;X        LD HL,(curangle) ;L=центр взгляда        LD C,(HL) ;sin=шаг по Y        LD A,-64        SUB L        LD L,A        LD B,(HL) ;-COS=шаг по X   ;Bc=DXdy=COSsin        LD A,C        CPL         CALL MULT ;HL=A*DE=-sin*Y       POP DE ;X        LD A,B        CALL MULTADD ;HL=-COS*X-sin*Y=d(расстояние по объекта)       POP DE ;Y        BIT 7,H        jr NZ,OBJMULQ ;если расстояние<0,то объект за спиной=>exit        LD (_OBJd1),HL        CALL MULT;A=B=-COS, HL=-COS*Y       POP DE ;X        LD A,C        CALL MULTADD ;HL=-COS*Y+sin*X=xscr*d        EXD _OBJd1=$+1        LD BC,0 ;BC=d ;после MONDIV получим DE=xscr;деление;DE=+-7.8;BC=+7.8;DE=DE/BC=+-8.7/2    ;BC сохраняется!!!;MONDIV        LD H,0        LD A,D        SLA E        RLA         JP C,MONDIVNEG ;если делимое<0        LD L,A        INC E        LD A,E       DUP 7        SBC HL,BC        JR NC,$+3        ADD HL,BC        RLA         ADC HL,HL       EDUP         CPL         LD D,A       DUP 7        SBC HL,BC        JR NC,$+3        ADD HL,BC        RLA         ADD HL,HL       EDUP         SBC HL,BC        JR NC,$+3        ADD HL,BC        RLA         CPL         LD E,A        RET ;если делимое<0MONDIVNEG        CPL         LD L,A        SBC A,A        XOR E       DUP 7        SBC HL,BC        JR NC,$+3        ADD HL,BC        RLA         ADC HL,HL       EDUP         LD D,A       DUP 7        SBC HL,BC        JR NC,$+3        ADD HL,BC        RLA         ADD HL,HL       EDUP         SBC HL,BC        JR NC,$+3        ADD HL,BC        RLA         LD E,A        RET ;умножение;A=+-0.7;HL=A*DE    ;A сохраняется!!!MULT        LD HL,0MULTADD        RLCA         JR NC,MULTPLU        DUP 6        SRA D        RR E        RLCA         JR C,$+4        SBC HL,DE        EDUP         RLCA         RET C        SRA D        RR E         OR A        SBC HL,DE        RET MULTPLU DUP 6        SRA D        RR E        RLCA         JR NC,$+3        ADD HL,DE        EDUP         RLCA         RET NC        SRA D        RR E        ADD HL,DE        RET        ENDIF ;sprites